    /**
     * {@inheritdoc}
     */
    public function run(): string
    {
        $sizeClass = $this->sizes[$this->size] ?? $this->sizes['md'];
        $path = $this->icons[$this->name] ?? '';

        if (empty($path)) {
            return '';
        }

        $class = trim($sizeClass . ' ' . ($this->class ?? ''));

        // Social icons use fill, others use stroke
        $isSocial = in_array($this->name, ['instagram', 'whatsapp', 'telegram']);

        if ($isSocial) {
            return Html::tag('svg', Html::tag('path', '', ['d' => $path]), [
                'class' => $class,
                'fill' => 'currentColor',
                'viewBox' => '0 0 24 24',
                'aria-hidden' => 'true',
            ]);
        }

        return Html::tag('svg', Html::tag('path', '', [
            'stroke-linecap' => 'round',
            'stroke-linejoin' => 'round',
            'd' => $path,
        ]), [
            'class' => $class,
            'fill' => 'none',
            'stroke' => 'currentColor',
            'stroke-width' => '1.5',
            'viewBox' => '0 0 24 24',
            'aria-hidden' => 'true',
        ]);
    }

    /**
     * Static shortcut method
     */
    public static function show(string $name, string $size = 'md', ?string $class = null): string
    {
        return self::widget([
            'name' => $name,
            'size' => $size,
            'class' => $class,
        ]);
    }
